            [0, 0, 0, 0, 8, 0, 0, 0, 0]
        ];
        const numbers = "123456789".split('');

        function generateGrid() {
            const cells = Array.from({ length: 81 }, () => ({
                cell: undefined,
                value: '',
                selected: false,
                error: false
            }));

            numbers.forEach(number => {
                cells.filter(cell => cell.value === number).forEach(cell => {
