                if (cell.selected) grid.appendChild(document.createElement("div")).className = "selected";
            });
        }

        function resetGame() {
            document.getElementById("sudoku-grid").innerHTML = "";
            generateGrid();
        }

        function onCellClick(event) {
            const cell = event.target;
            cell.classList.toggle("selected");
            if (cell.value === '') {
                const value = prompt("Enter a number (1-9): ");
                cell.value = value;
                if (value.match(/[^1-9]/i)) return; // Validation
            } else if (cell.value > 9) {
                cell.value = '';
                cell.classList.remove("selected");
                cell.classList.add("error");
            }
        }

        function onCellChange(event) {
            const cell = event.target;
            cell.classList.toggle("error", cell.value === '');
            cell.classList.toggle("selected", cell.value !== '');
        }

        newGameButton.addEventListener("click", resetGame);
        grid.addEventListener("click", onCellClick);
        grid.addEventListener("input", onCellChange);

        generateGrid();
